<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link } from '@inertiajs/vue3';
import axios from 'axios';
import { computed, ref } from 'vue';

const props = defineProps<{ profileUser: any; posts: any; friendship: any; following: boolean }>();
const friendship = ref(props.friendship);
const following = ref(props.following);
const activeTab = ref('Posts');
const posts = ref<any[]>(props.posts.data || []);
const photos = computed(() => posts.value.flatMap(post => (post.media || []).filter((media: any) => media.type === 'image')).slice(0, 9));
const joined = computed(() => props.profileUser.joined_at ? new Intl.DateTimeFormat(undefined, { month: 'long', year: 'numeric' }).format(new Date(props.profileUser.joined_at)) : '');
const ago = (value: string) => { const hours = Math.floor((Date.now() - new Date(value).getTime()) / 3600000); return hours < 1 ? 'Just now' : hours < 24 ? `${hours}h` : hours < 168 ? `${Math.floor(hours / 24)}d` : new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' }).format(new Date(value)); };
async function add() { const { data } = await axios.post(`/users/${props.profileUser.id}/friendships`); friendship.value = data.data; }
async function respond(action: string) { const { data } = await axios.post(`/friendships/${friendship.value.id}`, { action }); friendship.value = data.data; }
async function removeFriend() { await axios.delete(`/friendships/${friendship.value.id}`); friendship.value = null; }
async function toggleFollow() { await axios({ method: following.value ? 'delete' : 'post', url: `/users/${props.profileUser.id}/follow` }); following.value = !following.value; }
</script>

<template>
    <Head :title="profileUser.name" />
    <AuthenticatedLayout>
        <div class="min-h-screen bg-[#f0f2f5] pb-10">
            <div class="mx-auto max-w-[1100px]">
                <section class="overflow-hidden bg-white shadow-sm sm:rounded-b-xl">
                    <div class="relative h-48 bg-gradient-to-br from-sky-300 via-blue-400 to-indigo-600 sm:h-72" :style="profileUser.cover_photo_url ? { backgroundImage: `url(${profileUser.cover_photo_url})`, backgroundSize: 'cover', backgroundPosition: 'center' } : {}"><span v-if="!profileUser.cover_photo_url" class="absolute inset-0 bg-[radial-gradient(circle_at_75%_15%,rgba(255,255,255,.38),transparent_30%)]" /></div>
                    <div class="relative px-4 sm:px-8"><div class="flex flex-col gap-3 sm:flex-row sm:items-end"><div class="-mt-16 grid h-36 w-36 shrink-0 place-items-center overflow-hidden rounded-full border-4 border-white bg-gradient-to-br from-indigo-500 to-violet-600 text-5xl font-bold text-white shadow-md sm:-mt-20 sm:h-40 sm:w-40"><img v-if="profileUser.avatar_url" :src="profileUser.avatar_url" class="h-full w-full object-cover" :alt="profileUser.name"><span v-else>{{ profileUser.name?.[0] }}</span></div><div class="min-w-0 pb-2 sm:flex-1"><h1 class="truncate text-3xl font-bold text-slate-900">{{ profileUser.name }}</h1><p class="mt-1 text-[15px] font-medium text-slate-500"><Link :href="route('friends')">{{ profileUser.friends_count }} friends</Link> · <Link :href="route('social.connections', [profileUser.id, 'followers'])">{{ profileUser.followers_count }} followers</Link> · <Link :href="route('social.connections', [profileUser.id, 'following'])">{{ profileUser.following_count }} following</Link></p></div><div class="flex gap-2 pb-3"><Link v-if="profileUser.id === $page.props.auth.user.id" :href="route('profile.edit')" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-blue-700">✎ Edit profile</Link><template v-else><button v-if="!friendship" @click="add" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-blue-700">＋ Add friend</button><button v-else-if="friendship.status === 'pending' && friendship.receiver_id === $page.props.auth.user.id" @click="respond('accept')" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Confirm</button><button v-else-if="friendship.status === 'accepted'" @click="removeFriend" class="rounded-lg bg-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700">✓ Friends</button><button v-else-if="friendship.sender_id === $page.props.auth.user.id" @click="removeFriend" class="rounded-lg bg-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700">Request sent</button><button v-else @click="respond('decline')" class="rounded-lg bg-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700">Delete request</button><button @click="toggleFollow" class="rounded-lg bg-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700">{{ following ? 'Following' : 'Follow' }}</button><Link :href="route('dashboard')" class="grid h-10 w-10 place-items-center rounded-lg bg-slate-200 text-slate-700 hover:bg-slate-300" title="Message">✉</Link></template></div></div><nav class="mt-2 flex gap-1 overflow-x-auto border-t border-slate-200"><button v-for="tab in ['Posts', 'About', 'Friends', 'Photos']" :key="tab" @click="activeTab = tab" class="shrink-0 border-b-[3px] px-4 py-4 text-sm font-semibold" :class="activeTab === tab ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-600 hover:bg-slate-50'">{{ tab }}</button></nav></div>
                </section>
                <div class="grid gap-4 px-3 pt-4 lg:grid-cols-[410px_minmax(0,1fr)] lg:px-0"><aside class="space-y-4"><section class="rounded-xl bg-white p-4 shadow-sm ring-1 ring-slate-200/70"><h2 class="text-xl font-bold">Intro</h2><p class="mt-3 text-center text-sm leading-6 text-slate-600">Welcome to {{ profileUser.name }}'s profile.</p><div class="mt-4 space-y-3 border-t border-slate-100 pt-4 text-[15px] text-slate-700"><p>👤 Username <b>@{{ profileUser.username }}</b></p><p v-if="joined">🗓 Joined {{ joined }}</p><p>👥 <b>{{ profileUser.friends_count }}</b> friends</p></div><Link v-if="profileUser.id === $page.props.auth.user.id" :href="route('profile.edit')" class="mt-4 block rounded-lg bg-slate-100 py-2 text-center text-sm font-semibold text-slate-700 hover:bg-slate-200">Edit details</Link></section><section class="rounded-xl bg-white p-4 shadow-sm ring-1 ring-slate-200/70"><div class="flex items-center justify-between"><h2 class="text-xl font-bold">Photos</h2><button @click="activeTab = 'Photos'" class="text-sm font-medium text-blue-600 hover:underline">See all photos</button></div><p class="mt-1 text-sm text-slate-500">{{ profileUser.photos_count }} photos</p><div v-if="photos.length" class="mt-3 grid grid-cols-3 gap-1 overflow-hidden rounded-lg"><img v-for="photo in photos" :key="photo.id" :src="photo.url" class="aspect-square w-full object-cover" alt="Profile photo"></div><p v-else class="mt-3 rounded-lg bg-slate-50 p-4 text-center text-sm text-slate-500">No public photos yet.</p></section></aside>
                    <main class="min-w-0 space-y-4"><section v-if="activeTab !== 'Posts'" class="rounded-xl bg-white p-8 text-center shadow-sm ring-1 ring-slate-200/70"><p class="text-3xl">{{ activeTab === 'Friends' ? '👥' : activeTab === 'Photos' ? '🖼️' : 'ℹ️' }}</p><h2 class="mt-3 text-lg font-bold">{{ activeTab }}</h2><p class="mt-1 text-sm text-slate-500">More {{ activeTab.toLowerCase() }} from {{ profileUser.name }} will appear here.</p></section><template v-else><section v-if="profileUser.id === $page.props.auth.user.id" class="rounded-xl bg-white p-3 shadow-sm ring-1 ring-slate-200/70"><div class="flex items-center gap-3"><span class="grid h-10 w-10 place-items-center rounded-full bg-blue-600 font-bold text-white">{{ profileUser.name?.[0] }}</span><Link :href="route('feed')" class="flex-1 rounded-full bg-slate-100 px-4 py-2.5 text-sm text-slate-500 hover:bg-slate-200">What's on your mind?</Link></div></section><article v-for="post in posts" :key="post.id" class="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-slate-200/70"><header class="flex items-center gap-3 p-4"><span class="grid h-10 w-10 place-items-center overflow-hidden rounded-full bg-indigo-600 font-bold text-white"><img v-if="post.author.avatar_url" :src="post.author.avatar_url" class="h-full w-full object-cover" alt=""><template v-else>{{ post.author.name?.[0] }}</template></span><div><p class="font-semibold text-slate-900">{{ post.author.name }}</p><p class="text-xs text-slate-500">{{ ago(post.created_at) }} · {{ post.privacy === 'public' ? '🌐' : '👥' }}</p></div></header><p v-if="post.content" class="whitespace-pre-wrap px-4 pb-3 leading-relaxed text-slate-800">{{ post.content }}</p><div v-if="post.media?.length" class="grid grid-cols-2 gap-0.5 bg-slate-100" :class="post.media.length === 1 ? 'grid-cols-1' : ''"><template v-for="media in post.media.slice(0, 4)" :key="media.id"><img v-if="media.type === 'image'" :src="media.url" class="max-h-[430px] h-full w-full object-cover" alt="Post image"><video v-else :src="media.url" controls class="max-h-[430px] w-full bg-black" /></template></div><div class="flex items-center justify-between px-4 py-3 text-sm text-slate-500"><span>{{ Object.values(post.reactions || {}).reduce((sum: number, count: any) => sum + Number(count), 0) || 'No' }} reactions</span><span>{{ post.comments_count }} comments · {{ post.shares_count }} shares</span></div><div class="mx-4 grid grid-cols-3 border-t border-slate-100 py-1 text-sm font-semibold text-slate-600"><button class="rounded-md py-2 hover:bg-slate-100">♡ Like</button><button class="rounded-md py-2 hover:bg-slate-100">▢ Comment</button><button class="rounded-md py-2 hover:bg-slate-100">↗ Share</button></div></article><section v-if="!posts.length" class="rounded-xl bg-white p-10 text-center shadow-sm ring-1 ring-slate-200/70"><p class="text-4xl">📝</p><h2 class="mt-3 font-bold">No posts yet</h2><p class="mt-1 text-sm text-slate-500">{{ profileUser.name }} has not shared anything visible to you.</p></section></template></main></div>
            </div>
        </div>
    </AuthenticatedLayout>
</template>
